""" Helper method to process slice keys """
def _global_to_local_key_slice(
    global_key: Any, globalshape: Any, local_to_global_dict: Any, axis: Any = 0
) -> object {
    if (global_key == slice(None)) {
        return global_key;
    }
    if (local_to_global_dict is None) {
        return global_key;
    }
    (global_start, global_stop, global_step) = global_key.indices(globalshape[axis]);
    (global_min, global_max) = local_to_global_dict[axis];
    global_start = global_start if (global_start is not None) else 0;
    global_stop = global_stop if (global_stop is not None) else globalshape[axis];
    local_start = global_start - global_min;
    local_stop = global_stop - global_min;
    local_key = slice(local_start, local_stop, global_step);
    return local_key;
}

"""Parse options given in str.

    When options = 'cutoff = 4.0', options is converted to {'cutoff': 4.0}.

    In this implementation (can be modified), using phonopy command line
    options, ``options`` is passed by  --fc-calc-opt such as::

       phonopy --hiphiveph --fc-calc-opt "cutoff = 4" ...

    """
def _decode_options(options: Any) -> object {
    option_dict = {};
    for pair in options.split(",") {
        (key, value) = [x.strip() for x in pair.split("=")];
        if (key == "cutoff") {
            option_dict[key] = float(value);
        }
    }
    return option_dict;
}

